// 2 分钟超时——sessions 目录可能很大。改后台任务跑统计
const bg = await tools.pwsh({
  command: `
$out = @()
foreach ($d in @("$env:DSH_HOME\.dsh-memory", "$env:USERPROFILE\.openviking", "$env:DSH_HOME\grill-first", "$env:DSH_HOME\sessions", "$env:DSH_HOME\storages")) {
  if (Test-Path $d) {
    $m = Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
    $out += ("{0}|{1:N2}|{2}" -f (Split-Path $d -Leaf), ($m.Sum/1MB), $m.Count)
  }
}
$out | Set-Content "D:\\GitHub\\_size_report.txt" -Encoding UTF8
`,
  description: "后台统计数据体积",
  run_in_background: true
});
return bg.jobId;
